package ug.audiocity.studio;
import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;import org.json.*;
public class SoundTests {
 static int passed;static void check(boolean c,String m){if(!c)throw new AssertionError(m);passed++;}
 static double rms(float[] data,int start,int end){double sum=0;for(int i=start;i<end;i++)sum+=data[2*i]*data[2*i];return Math.sqrt(sum/(end-start));}
 public static void main(String[] args)throws Exception {File base=new File(args.length>0?args[0]:"assets");JSONObject manifest=new JSONObject(new String(Files.readAllBytes(new File(base,"samples/manifest.json").toPath()),"UTF-8"));JSONArray sounds=manifest.getJSONArray("sounds");check(sounds.length()>=29,"Expected at least 29 sample assets");int loops=0;for(int n=0;n<29;n++){JSONObject e=sounds.getJSONObject(n);File file=new File(base,"samples/"+e.getString("file"));float[] data;try(InputStream in=new FileInputStream(file)){data=SampleAudio.readWav(in);}check(data.length/2==e.getInt("frames"),e.getString("id")+" frame count");double peak=0,energy=0;for(float sample:data){peak=Math.max(peak,Math.abs(sample));energy+=sample*sample;}check(peak<1&&energy/data.length>1e-8,e.getString("id")+" is non-silent and not clipped");check(e.getString("license").equals("CC0-1.0")&&e.getString("source").startsWith("https://"),"Source and licence metadata");MessageDigest digest=MessageDigest.getInstance("SHA-256");StringBuilder hash=new StringBuilder();for(byte b:digest.digest(Files.readAllBytes(file.toPath())))hash.append(String.format("%02x",b&255));check(hash.toString().equals(e.getString("assetSha256")),"Asset digest");if(e.getInt("bpm")>0){loops++;int expected=(int)Math.round(Core.RATE*60.0/e.getInt("bpm")*4*e.getInt("bars"));check(data.length/2==expected,"Loop is aligned to its BPM and bar length");float[] fitted=SampleAudio.fitLoop(data,e.getInt("bars"),100);check(fitted.length/2==48000*60/100*4*e.getInt("bars"),"Tempo fit produces project-length loop");}}check(loops==5,"Expected 5 Afrobeat loop variations");
 Set<Integer> fingerprints=new HashSet<>();for(int patch=0;patch<Synth.NAMES.length;patch++){float[] note=Synth.note(60,.6,Synth.factory(patch));boolean finite=true;for(float x:note)finite&=Float.isFinite(x)&&Math.abs(x)<1;check(finite&&rms(note,0,note.length/2)>1e-4,"Synth patch has finite non-silent audio: "+Synth.NAMES[patch]);check(note[note.length-1]==0&&note[note.length-2]==0,"Synth release reaches zero");fingerprints.add(Arrays.hashCode(note));}check(fingerprints.size()==Synth.NAMES.length,"All patches produce distinct audio");{int[] seen=new int[Synth.NAMES.length];for(int[] list:Synth.SECTION_PATCHES)for(int q:list)seen[q]++;for(int q=0;q<seen.length;q++)check(seen[q]==1&&Synth.SECTION_PATCHES[Synth.sectionOf(q)].length>0,"Every patch is in exactly one section: "+Synth.NAMES[q]);check(Synth.SECTIONS.length==Synth.SECTION_PATCHES.length,"Section names match lists");}
 Synth.Config slow=Synth.factory(4);slow.attack=.6;Synth.Config fast=slow.copy();fast.attack=.001;check(rms(Synth.note(60,.8,slow),0,2400)<rms(Synth.note(60,.8,fast),0,2400)*.4,"Attack control changes envelope");Synth.Config shortRelease=Synth.factory(0),longRelease=shortRelease.copy();shortRelease.release=.1;longRelease.release=.7;check(Math.abs((Synth.note(60,.4,longRelease).length-Synth.note(60,.4,shortRelease).length)/2-28800)<2,"Release changes note duration");Synth.Config dark=Synth.factory(6),bright=dark.copy();dark.tone=0;bright.tone=1;float[] d=Synth.note(60,.4,dark),b=Synth.note(60,.4,bright);double de=0,be=0;for(int i=2;i<18000;i+=2){de+=Math.pow(d[i]-d[i-2],2);be+=Math.pow(b[i]-b[i-2],2);}check(be>de*2,"Tone control changes high-frequency energy");Synth.Config center=Synth.factory(4),wide=center.copy();center.detune=0;wide.detune=20;float[] mono=Synth.note(60,.5,center),stereo=Synth.note(60,.5,wide);double md=0,sd=0;for(int i=0;i<mono.length;i+=2){md+=Math.abs(mono[i]-mono[i+1]);sd+=Math.abs(stereo[i]-stereo[i+1]);}check(md==0&&sd>1,"Detuning introduces stereo variation");
 float[][] voices={{.5f,.5f,0,0}};boolean[][] steps=new boolean[1][16];steps[0][6]=true;float[] pattern=SampleAudio.pattern(100,steps,voices,new float[]{.8f},1);check(Math.abs(pattern[43200*2]-.4)<1e-6&&pattern[0]==0,"Sample sequencer places a weighted hit on step seven");steps[0][6]=false;check(rms(SampleAudio.pattern(100,steps,voices,new float[]{1},1),0,1000)==0,"Empty sampled pattern stays silent");
 boolean rejected=false;try{SampleAudio.readWav(new ByteArrayInputStream(new byte[44]));}catch(IOException e){rejected=true;}check(rejected,"Invalid sample WAV is rejected");
 System.out.println(passed+" sample-bank, synthesis and sequencing checks passed.");}
}
